ng_point": "Success is not measured by whether you ate the food.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Celiac Disease Foundation cross-contact guidance + teen lived-experience extension", "source_title": null, "source_url": "https://celiac.org/wp-content/uploads/2026/02/Cross-Contact-Handout.pdf", "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "3331f8d5-3f14-5210-aad4-2b623a3866d1", "content_type": "MYTH_OR_FACT", "title": "I have to explain celiac disease to everyone who asks.", "subtitle": null, "domain": "SPEAK", "topic": "Boundaries", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_014", "domains": ["SPEAK", "LIVE"], "original_metadata": {"content_id": "MOF_014", "content_type": "MYTH_OR_FACT", "statement": "I have to explain celiac disease to everyone who asks.", "answer_type": "MYTH", "domain": "SPEAK, LIVE", "topic": "Boundaries", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "You can choose how much personal health information you want to share. Sometimes a detailed explanation helps; sometimes a short answer or boundary is enough.", "takeaway": "Self-advocacy includes deciding how much you want to explain.", "source_organization": "Teen self-management content; expert review required", "source_url": null, "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "MYTH", "summary": "You can choose how much personal health information you want to share. Sometimes a detailed explanation helps; sometimes a short answer or boundary is enough."}, "teaching_point": "Self-advocacy includes deciding how much you want to explain.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Teen self-management content; expert review required", "source_title": null, "source_url": null, "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "6884538d-c6d8-59fd-a862-b053a3ceece0", "content_type": "MYTH_OR_FACT", "title": "Good self-advocacy can include saying, “No thanks.”", "subtitle": null, "domain": "SPEAK", "topic": "Self-Advocacy", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_015", "domains": ["SPEAK", "TRUST"], "original_metadata": {"content_id": "MOF_015", "content_type": "MYTH_OR_FACT", "statement": "Good self-advocacy can include saying, “No thanks.”", "answer_type": "FACT", "domain": "SPEAK, TRUST", "topic": "Self-Advocacy", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Self-advocacy is not only asking for accommodations. It can also mean politely declining food or a situation that does not work for you.", "takeaway": "You are allowed to say no without apologizing for having celiac disease.", "source_organization": "Celiac Disease Foundation + teen lived-experience extension", "source_url": "https://celiac.org/wp-content/uploads/2026/02/Cross-Contact-Handout.pdf", "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "FACT", "summary": "Self-advocacy is not only asking for accommodations. It can also mean politely declining food or a situation that does not work for you."}, "teaching_point": "You are allowed to say no without apologizing for having celiac disease.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Celiac Disease Foundation + teen lived-experience extension", "source_title": null, "source_url": "https://celiac.org/wp-content/uploads/2026/02/Cross-Contact-Handout.pdf", "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "ac89691c-87c3-5d4b-aed5-8948d3bcf5a3", "content_type": "MYTH_OR_FACT", "title": "If a host worked hard to make something gluten-free for me, I should eat it so I don't hurt their feelings.", "subtitle": null, "domain": "TRUST", "topic": "Social Situations", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_016", "domains": ["TRUST", "SPEAK", "LIVE"], "original_metadata": {"content_id": "MOF_016", "content_type": "MYTH_OR_FACT", "statement": "If a host worked hard to make something gluten-free for me, I should eat it so I don't hurt their feelings.", "answer_type": "MYTH", "domain": "TRUST, SPEAK, LIVE", "topic": "Social Situations", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "You can appreciate someone's effort and still ask questions or decide not to eat. Gratitude does not require overriding your own food decision.", "takeaway": "You can be kind to the host and still make your own decision.", "source_organization": "Teen lived-experience synthesis; expert review required", "source_url": null, "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "MYTH", "summary": "You can appreciate someone's effort and still ask questions or decide not to eat. Gratitude does not require overriding your own food decision."}, "teaching_point": "You can be kind to the host and still make your own decision.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Teen lived-experience synthesis; expert review required", "source_title": null, "source_url": null, "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "9204566a-b280-5d45-a598-88a1cc179aae", "content_type": "MYTH_OR_FACT", "title": "If I've had celiac disease for years, I shouldn't need help anymore.", "subtitle": null, "domain": "LIVE", "topic": "Independence", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_017", "domains": ["LIVE", "MANAGE"], "original_metadata": {"content_id": "MOF_017", "content_type": "MYTH_OR_FACT", "statement": "If I've had celiac disease for years, I shouldn't need help anymore.", "answer_type": "MYTH", "domain": "LIVE, MANAGE", "topic": "Independence", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Experience can build skills, but it does not mean every situation becomes effortless. Planning fatigue, unfamiliar settings and social challenges can still happen.", "takeaway": "Independence can include knowing when to use support.", "source_organization": "Teen lived-experience synthesis; expert review required", "source_url": null, "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "MYTH", "summary": "Experience can build skills, but it does not mean every situation becomes effortless. Planning fatigue, unfamiliar settings and social challenges can still happen."}, "teaching_point": "Independence can include knowing when to use support.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Teen lived-experience synthesis; expert review required", "source_title": null, "source_url": null, "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "01efb96d-98d2-59df-9a37-a6cfd4a2523d", "content_type": "MYTH_OR_FACT", "title": "My friends can be part of my celiac support system.", "subtitle": null, "domain": "LIVE", "topic": "Support", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_018", "domains": ["LIVE", "LEAD"], "original_metadata": {"content_id": "MOF_018", "content_type": "MYTH_OR_FACT", "statement": "My friends can be part of my celiac support system.", "answer_type": "FACT", "domain": "LIVE, LEAD", "topic": "Support", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Friends can help in practical ways: planning together, learning about cross-contact, asking rather than assuming what works for you, or simply helping you feel included.", "takeaway": "Support does not have to come only from parents or healthcare professionals.", "source_organization": "Teen lived-experience synthesis; expert review required", "source_url": null, "review_note": "Keep this item flagged for expert review 